  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.decision_policy (key, value, description) values ('refund_late_fee_annual_pct', to_jsonb(12::numeric), $qd$what the seats and the customer texts state (the current version's rate). Source: src/content/company_facts.json 2026-10-19.1.$qd$)
  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.decision_policy (key, value, description) values ('supplier_nonresponse_interest_apr_from_v14', to_jsonb(0.12::numeric), $qd$what fn_accountant_nonresponse_charge charges a supplier who accepted v14 or later before the reveal. Source: src/content/company_facts.json 2026-10-19.1.$qd$)
  on conflict (key) do update set value = excluded.value, updated_at = now();

-- re-render the company knowledge the seats read
do $s$ begin perform public.fn_company_org_directory_sync(); perform public.fn_company_self_knowledge_sync(); end $s$;

-- verdict
select case when (select count(*) = 1 from public.legal_documents where slug = 'customer-terms' and version = 'v11' and content_sha256 = 'b7bf27219950e172f8778bcb8b4ebcb53b0d3ccc14b1f92291160e74c0101a35')
   and (select count(*) = 1 from public.legal_documents where slug = 'supplier-agreement' and version = 'v16' and content_sha256 = '2b587a749624795e25ecc6d97351dfbb6bc1e1cd9bdc871240e52cb9440a561d')
   and (select value from public.app_secrets where key = 'customer_terms_version') = 'v11'
   and (select value from public.app_secrets where key = 'terms_version') = 'v16'
  then 'PROBE OK' else 'PROBE FAILED: the registry does not carry the generated bodies and versions' end as verdict;
